import com.android.tools.smali.dexlib2.*;import com.android.tools.smali.dexlib2.iface.instruction.*;import com.android.tools.smali.dexlib2.iface.reference.*;
public class InspectString{public static void main(String[]a)throws Exception{var c=DexFileFactory.loadDexContainer(new java.io.File(a[0]),Opcodes.forDexVersion(39));for(var n:c.getDexEntryNames())for(var cl:c.getEntry(n).getDexFile().getClasses())for(var m:cl.getMethods())if(m.getImplementation()!=null)for(var i:m.getImplementation().getInstructions())if(i instanceof ReferenceInstruction r && r.getReference() instanceof StringReference s && s.getString().contains(a[1]))System.out.println(n+" "+m+" "+s.getString());}}
